import{_ as t,o as l,c as i,a2 as e}from"./chunks/framework.CqpfiAoK.js";const q=JSON.parse('{"title":"文档版本与维护说明","description":"","frontmatter":{},"headers":[],"relativePath":"zh/99-文档版本与维护说明.md","filePath":"zh/99-文档版本与维护说明.md","lastUpdated":1789183869000}'),r={name:"zh/99-文档版本与维护说明.md"};function o(h,a,d,n,s,u){return l(),i("div",null,[...a[0]||(a[0]=[e('<h1 id="文档版本与维护说明" tabindex="-1">文档版本与维护说明 <a class="header-anchor" href="#文档版本与维护说明" aria-label="Permalink to &quot;文档版本与维护说明&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项目</th><th>内容</th></tr></thead><tbody><tr><td>文档编号</td><td>99</td></tr><tr><td>所属模块</td><td>附录与参考资料</td></tr><tr><td>核心关键词</td><td>版本管理、维护说明、文档规范、更新日志、设定维护</td></tr></tbody></table><h2 id="一、文档体系概述" tabindex="-1">一、文档体系概述 <a class="header-anchor" href="#一、文档体系概述" aria-label="Permalink to &quot;一、文档体系概述&quot;">​</a></h2><p>锚点共生文明设定体系由100份Markdown文档组成，编号从00至99，分为十大模块，每个模块10份文档。文档体系以SPEC.md（文档生成规范）为硬约束，以00-衡元宙宇宙总览为总纲，各模块文档从不同维度展开详述，最终以90-99附录文档进行索引、汇总与整理。整个文档体系构成一个逻辑自洽、层次分明、互相引用的完整设定知识库。</p><p>文档体系的设计遵循&quot;模块化、结构化、可扩展&quot;三大原则。模块化指每个文档聚焦一个特定主题，独立成篇；结构化指所有文档遵循统一的格式规范，便于阅读与检索；可扩展指文档体系预留了充分的扩展空间，可以通过修订现有文档、增补新内容来持续完善设定。</p><h2 id="二、版本编号规则" tabindex="-1">二、版本编号规则 <a class="header-anchor" href="#二、版本编号规则" aria-label="Permalink to &quot;二、版本编号规则&quot;">​</a></h2><p>文档体系采用&quot;主版本号.次版本号.修订号&quot;的三级版本编号规则：</p><table tabindex="0"><thead><tr><th>版本层级</th><th>编号规则</th><th>触发条件</th><th>示例</th></tr></thead><tbody><tr><td>主版本号</td><td>从1开始递增</td><td>文档体系发生重大架构调整，如模块重新划分、核心设定变更</td><td>v1.0 → v2.0</td></tr><tr><td>次版本号</td><td>从0开始递增</td><td>某份文档的核心内容发生实质性修订，或新增重要设定内容</td><td>v1.0 → v1.1</td></tr><tr><td>修订号</td><td>从0开始递增</td><td>文档的文字修正、格式调整、术语统一等非实质性修改</td><td>v1.0 → v1.0.1</td></tr></tbody></table><p>当前文档体系的整体版本为v1.0，即首次完整发布版本。每份文档在其文档信息块中记录自身的版本号，文档体系的整体版本号在本文档中统一记录。</p><h2 id="三、文档格式规范回顾" tabindex="-1">三、文档格式规范回顾 <a class="header-anchor" href="#三、文档格式规范回顾" aria-label="Permalink to &quot;三、文档格式规范回顾&quot;">​</a></h2><p>所有文档必须遵循以下统一格式规范（详细规范见SPEC.md）：</p><h3 id="_3-1-文件命名" tabindex="-1">3.1 文件命名 <a class="header-anchor" href="#_3-1-文件命名" aria-label="Permalink to &quot;3.1 文件命名&quot;">​</a></h3><p>文件名格式为<code>XX-文档标题.md</code>，其中XX为00-99的两位数字编号，标题用中文，不含空格。</p><h3 id="_3-2-文档结构" tabindex="-1">3.2 文档结构 <a class="header-anchor" href="#_3-2-文档结构" aria-label="Permalink to &quot;3.2 文档结构&quot;">​</a></h3><p>每份文档必须包含以下结构要素：</p><ol><li><strong>一级标题</strong>：文档标题（与文件名一致）</li><li><strong>文档信息块</strong>：编号、所属模块、核心关键词（3-5个）的表格</li><li><strong>正文</strong>：至少3个二级标题章节，使用列表、表格等结构化元素</li><li><strong>结语</strong>：简短总结段落</li><li><strong>关联文档</strong>：列出2-3份相关文档编号与名称</li></ol><h3 id="_3-3-字数要求" tabindex="-1">3.3 字数要求 <a class="header-anchor" href="#_3-3-字数要求" aria-label="Permalink to &quot;3.3 字数要求&quot;">​</a></h3><p>每份文档正文不少于800字（不含标题和元信息）。</p><h3 id="_3-4-写作风格" tabindex="-1">3.4 写作风格 <a class="header-anchor" href="#_3-4-写作风格" aria-label="Permalink to &quot;3.4 写作风格&quot;">​</a></h3><ul><li>严肃、体系化的设定文档风格，类似百科全书/设定集</li><li>使用&quot;衡元宙&quot;&quot;锚点&quot;&quot;共生&quot;等统一术语</li><li>补充的新设定必须与已有设定逻辑自洽，符合&quot;现实为基、规律升级&quot;原则</li></ul><h2 id="四、维护组织与职责" tabindex="-1">四、维护组织与职责 <a class="header-anchor" href="#四、维护组织与职责" aria-label="Permalink to &quot;四、维护组织与职责&quot;">​</a></h2><h3 id="_4-1-设定维护委员会" tabindex="-1">4.1 设定维护委员会 <a class="header-anchor" href="#_4-1-设定维护委员会" aria-label="Permalink to &quot;4.1 设定维护委员会&quot;">​</a></h3><p>设定维护委员会是文档体系的最高维护机构，由资深设定创作者、逻辑校验专家与用户代表组成。其核心职责包括：</p><ul><li>审定文档体系的整体架构与重大修订方案</li><li>审核重大设定变更，确保与核心设定一致</li><li>裁决设定争议，给出权威解释</li><li>定期组织全面的设定一致性自查</li><li>发布文档体系的整体版本更新</li></ul><h3 id="_4-2-模块维护者" tabindex="-1">4.2 模块维护者 <a class="header-anchor" href="#_4-2-模块维护者" aria-label="Permalink to &quot;4.2 模块维护者&quot;">​</a></h3><p>每个模块指定一名模块维护者，负责该模块10份文档的日常维护。其职责包括：</p><ul><li>跟踪模块内文档的设定一致性</li><li>审核模块内文档的修订申请</li><li>协调模块内文档之间的交叉引用</li><li>收集用户对模块内容的反馈与建议</li><li>定期向设定维护委员会汇报模块维护状态</li></ul><h3 id="_4-3-文档创作者" tabindex="-1">4.3 文档创作者 <a class="header-anchor" href="#_4-3-文档创作者" aria-label="Permalink to &quot;4.3 文档创作者&quot;">​</a></h3><p>任何符合条件的创作者都可以参与文档的创作与修订。创作者的职责包括：</p><ul><li>按照格式规范创作或修订文档</li><li>确保创作内容通过设定矛盾自查表的检查</li><li>提交修订时附详细的修订说明</li><li>配合维护者与委员会的审核工作</li></ul><h2 id="五、修订流程" tabindex="-1">五、修订流程 <a class="header-anchor" href="#五、修订流程" aria-label="Permalink to &quot;五、修订流程&quot;">​</a></h2><h3 id="_5-1-常规修订流程" tabindex="-1">5.1 常规修订流程 <a class="header-anchor" href="#_5-1-常规修订流程" aria-label="Permalink to &quot;5.1 常规修订流程&quot;">​</a></h3><ol><li><strong>提交申请</strong>：创作者向模块维护者提交修订申请，包括修订文档编号、修订内容说明与修订理由。</li><li><strong>模块审核</strong>：模块维护者审核修订内容，重点检查格式规范与模块内一致性。审核通过后提交设定维护委员会。</li><li><strong>委员会审定</strong>：设定维护委员会对修订内容进行最终审定，重点检查跨模块一致性与核心设定一致性。</li><li><strong>执行修订</strong>：审定通过后，由模块维护者或原创作者执行文档修订。</li><li><strong>版本更新</strong>：修订完成后，更新文档版本号，并在本文档的更新日志中记录。</li><li><strong>关联同步</strong>：如果修订内容影响其他文档，须同步修订关联文档。</li></ol><h3 id="_5-2-紧急修订流程" tabindex="-1">5.2 紧急修订流程 <a class="header-anchor" href="#_5-2-紧急修订流程" aria-label="Permalink to &quot;5.2 紧急修订流程&quot;">​</a></h3><p>对于发现严重设定矛盾或错误的紧急情况，可启动紧急修订流程：</p><ol><li><strong>紧急报告</strong>：发现者立即向设定维护委员会报告问题。</li><li><strong>快速审定</strong>：委员会在24小时内完成紧急审定，给出修订方案。</li><li><strong>执行修订</strong>：指定专人立即执行修订。</li><li><strong>事后补录</strong>：修订完成后补录修订申请与审核记录。</li></ol><h3 id="_5-3-定期全面修订" tabindex="-1">5.3 定期全面修订 <a class="header-anchor" href="#_5-3-定期全面修订" aria-label="Permalink to &quot;5.3 定期全面修订&quot;">​</a></h3><p>设定维护委员会每年组织一次全面的文档体系修订，包括：</p><ul><li>全面的设定一致性自查</li><li>用户反馈的集中处理</li><li>术语体系的统一与更新</li><li>索引文档的同步更新</li><li>文档格式的统一检查与修正</li></ul><h2 id="六、更新日志" tabindex="-1">六、更新日志 <a class="header-anchor" href="#六、更新日志" aria-label="Permalink to &quot;六、更新日志&quot;">​</a></h2><h3 id="v1-0-首次完整发布" tabindex="-1">v1.0（首次完整发布） <a class="header-anchor" href="#v1-0-首次完整发布" aria-label="Permalink to &quot;v1.0（首次完整发布）&quot;">​</a></h3><ul><li>完成全部100份文档的创作与发布</li><li>建立完整的文档体系架构与格式规范</li><li>完成十大模块的内容覆盖</li><li>建立附录索引体系（术语词典、体系索引、法律索引、编年史、万族名录、人物组织、FAQ、自查表、扩展建议、版本说明）</li></ul><h3 id="后续版本更新记录区" tabindex="-1">后续版本更新记录区 <a class="header-anchor" href="#后续版本更新记录区" aria-label="Permalink to &quot;后续版本更新记录区&quot;">​</a></h3><p>（后续版本的更新内容将在此处追加记录，包括版本号、发布日期、主要更新内容摘要）</p><h2 id="七、文档引用与交叉引用规范" tabindex="-1">七、文档引用与交叉引用规范 <a class="header-anchor" href="#七、文档引用与交叉引用规范" aria-label="Permalink to &quot;七、文档引用与交叉引用规范&quot;">​</a></h2><h3 id="_7-1-内部引用" tabindex="-1">7.1 内部引用 <a class="header-anchor" href="#_7-1-内部引用" aria-label="Permalink to &quot;7.1 内部引用&quot;">​</a></h3><p>文档之间的交叉引用使用&quot;文档编号-文档标题&quot;的格式，例如&quot;参见文档84《考古协议总纲》&quot;。引用时应确保被引用文档确实存在且编号与标题正确。</p><h3 id="_7-2-术语引用" tabindex="-1">7.2 术语引用 <a class="header-anchor" href="#_7-2-术语引用" aria-label="Permalink to &quot;7.2 术语引用&quot;">​</a></h3><p>首次使用某个核心术语时，可注明参见文档90《术语词典》中的对应条目。后续使用同一术语时无需重复注明。</p><h3 id="_7-3-外部引用" tabindex="-1">7.3 外部引用 <a class="header-anchor" href="#_7-3-外部引用" aria-label="Permalink to &quot;7.3 外部引用&quot;">​</a></h3><p>如需引用设定体系之外的现实资料或虚构作品，应注明来源，并明确说明该引用属于&quot;现实为基&quot;原则下的参考素材，不代表设定体系对其内容的完全采纳。</p><h2 id="八、质量保证机制" tabindex="-1">八、质量保证机制 <a class="header-anchor" href="#八、质量保证机制" aria-label="Permalink to &quot;八、质量保证机制&quot;">​</a></h2><h3 id="_8-1-设定矛盾自查" tabindex="-1">8.1 设定矛盾自查 <a class="header-anchor" href="#_8-1-设定矛盾自查" aria-label="Permalink to &quot;8.1 设定矛盾自查&quot;">​</a></h3><p>所有新创作与修订的文档必须通过文档97《设定矛盾自查表》的全部检查项，包括核心设定一致性、跨模块逻辑一致性、文档格式规范三大类共40余项检查。</p><h3 id="_8-2-交叉审核" tabindex="-1">8.2 交叉审核 <a class="header-anchor" href="#_8-2-交叉审核" aria-label="Permalink to &quot;8.2 交叉审核&quot;">​</a></h3><p>每份文档在正式发布前须经过至少一位其他创作者的交叉审核，重点检查跨模块的逻辑一致性与术语统一性。</p><h3 id="_8-3-用户反馈机制" tabindex="-1">8.3 用户反馈机制 <a class="header-anchor" href="#_8-3-用户反馈机制" aria-label="Permalink to &quot;8.3 用户反馈机制&quot;">​</a></h3><p>文档体系设立用户反馈渠道，用户可以通过以下方式提交反馈：</p><ul><li>报告设定矛盾与逻辑错误</li><li>提出术语不统一的问题</li><li>建议补充或修订特定内容</li><li>指出格式与文字错误</li></ul><p>所有反馈由模块维护者分类处理，重要反馈提交设定维护委员会审议。</p><h3 id="_8-4-季度一致性报告" tabindex="-1">8.4 季度一致性报告 <a class="header-anchor" href="#_8-4-季度一致性报告" aria-label="Permalink to &quot;8.4 季度一致性报告&quot;">​</a></h3><p>设定维护委员会每季度发布一份《设定一致性报告》，内容包括：</p><ul><li>本季度发现的设定矛盾及处理情况</li><li>本季度文档修订统计</li><li>术语统一进展</li><li>用户反馈处理情况</li><li>下一季度维护计划</li></ul><h2 id="九、文档存储与分发" tabindex="-1">九、文档存储与分发 <a class="header-anchor" href="#九、文档存储与分发" aria-label="Permalink to &quot;九、文档存储与分发&quot;">​</a></h2><h3 id="_9-1-存储格式" tabindex="-1">9.1 存储格式 <a class="header-anchor" href="#_9-1-存储格式" aria-label="Permalink to &quot;9.1 存储格式&quot;">​</a></h3><p>所有文档以Markdown（.md）格式存储，确保跨平台可读性与版本管理的便利性。文档使用UTF-8编码，支持中文与特殊字符。</p><h3 id="_9-2-目录结构" tabindex="-1">9.2 目录结构 <a class="header-anchor" href="#_9-2-目录结构" aria-label="Permalink to &quot;9.2 目录结构&quot;">​</a></h3><p>文档统一存储在<code>anchor-docs/</code>目录下，文件名为<code>XX-文档标题.md</code>。SPEC.md作为规范文件也存储在同一目录下。</p><h3 id="_9-3-版本管理" tabindex="-1">9.3 版本管理 <a class="header-anchor" href="#_9-3-版本管理" aria-label="Permalink to &quot;9.3 版本管理&quot;">​</a></h3><p>建议使用Git等版本控制系统对文档进行版本管理，每次修订提交时附详细的commit message，记录修订内容与理由。</p><h3 id="_9-4-分发方式" tabindex="-1">9.4 分发方式 <a class="header-anchor" href="#_9-4-分发方式" aria-label="Permalink to &quot;9.4 分发方式&quot;">​</a></h3><p>文档体系可以通过以下方式分发：</p><ul><li>打包为ZIP压缩包下载</li><li>部署为静态网站在线浏览</li><li>转换为PDF或EPUB格式阅读</li><li>导入知识库系统进行结构化管理</li></ul><h2 id="结语" tabindex="-1">结语 <a class="header-anchor" href="#结语" aria-label="Permalink to &quot;结语&quot;">​</a></h2><p>文档版本与维护说明是锚点共生文明设定体系的&quot;管理宪法&quot;。它确立了文档体系的版本规则、维护组织、修订流程、质量保证机制与存储分发方式，确保这个由100份文档组成的庞大设定体系能够在持续生长的过程中始终保持秩序与一致性。一个好的设定体系不仅需要精彩的内容，更需要完善的维护机制来保障其长期健康发展。本文档正是这一机制的核心载体。</p><h2 id="关联文档" tabindex="-1">关联文档 <a class="header-anchor" href="#关联文档" aria-label="Permalink to &quot;关联文档&quot;">​</a></h2><ul><li>97-设定矛盾自查表</li><li>90-术语词典</li><li>00-衡元宙宇宙总览</li></ul>',77)])])}const b=t(r,[["render",o]]);export{q as __pageData,b as default};
